    """Return the arithmetic mean of *values*.

    Raises ``ValueError`` for empty input, non-numeric entries,
    or missing (None) values.
    """
    if not values:
        raise ValueError("empty column")

    for i, v in enumerate(values):
        if v is None:
            raise ValueError(f"missing value at index {i}")
        if not isinstance(v, (int, float)):
            raise ValueError(f"non-numeric value at index {i}: {v!r}")

    return sum(values) / len(values)
